package com.bank.liquidity.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Largest absolute continuous cash swing: dual (max + min) Kadane in one pass.
public class ExtremeSwingAnalyzer {
    private static final Logger log = Logger.getLogger(ExtremeSwingAnalyzer.class.getName());

    public long largestAbsoluteSwing(int[] swings) {
        if (swings == null || swings.length == 0) {
            throw new IllegalArgumentException("Swing sequence must be non-empty");
        }
        long curMax = swings[0], globalMax = swings[0];
        long curMin = swings[0], globalMin = swings[0];

        for (int i = 1; i < swings.length; i++) {
            int x = swings[i];
            curMax = Math.max(x, curMax + x);
            curMin = Math.min(x, curMin + x);
            globalMax = Math.max(globalMax, curMax);
            globalMin = Math.min(globalMin, curMin);
            final int day = i;
            final long cMax = curMax, cMin = curMin;
            log.fine(() -> "Day " + day + ": curMax=" + cMax + " curMin=" + cMin);
        }
        long answer = Math.max(globalMax, Math.abs(globalMin));
        final long a = answer, gMax = globalMax, gMin = globalMin;
        log.info(() -> "Largest absolute swing over " + Arrays.toString(swings)
                + " = max(" + gMax + ", |" + gMin + "|) = " + a);
        return answer;
    }
}
